n experience required.","place_id":"10000000-0000-0000-0000-000000000009","source":"manual","source_url":null,"image_url":"/ads/labba.webp"},{"id":"30000000-0000-0000-0000-000000000008","title":"Grad Ball 2027","org":"SUS","starts_at":"2027-04-10T23:00:00+00:00","location":"Downtown Montreal","description":"The final boss of McGill events.","place_id":null,"source":"manual","source_url":null,"image_url":null},{"id":"30000000-0000-0000-0000-000000000005","title":"SUS Holiday Social","org":"SUS","starts_at":"2026-11-18T23:00:00+00:00","location":"Trottier Building","description":"Hot chocolate, ugly sweaters, avoiding finals.","place_id":null,"source":"manual","source_url":null,"image_url":null}]$snapshot$);

